#include <vector>
#include <algorithm>

void show_result(unsigned v)
{
    std::cout << v << '\n';
}

void find_and_output(const std::vector<unsigned>& data)
{
    auto [it_min, it_max] = std::minmax_element(data.begin(), data.end());
    unsigned min_val = *it_min;
    unsigned max_val = *it_max;
    show_result(min_val + (max_val - min_val) / 2);
}

int main()
{
    size_t n;
    std::cin >> n;
    std::vector<unsigned> input(n);
    for (size_t i = 0; i < n; ++i)
        std::cin >> input[i];

    find_and_output(input);
    return 0;
}
