import java.util.*;
import java.util.stream.*;

public class Main {
    public static void showResult(long v) {
        System.out.println(v);
    }

    public static void findAndOutput(List<Long> data) {
        long minVal = Collections.min(data);
        long maxVal = Collections.max(data);
        showResult(minVal + (maxVal - minVal) / 2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Long> input = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            input.add(sc.nextLong());
        }
        findAndOutput(input);
        sc.close();
    }
}
